import pytest

from dates import days_between, business_days, next_monday


def test_inclusive_across_month():
    days = days_between(date(2024, 1, 30), date(2024, 2, 2))
    assert days == [date(2024, 1, 30), date(2024, 1, 31), date(2024, 2, 1), date(2024, 2, 2)]


def test_start_equals_end():
    days = days_between(date(2024, 1, 30), date(2024, 1, 30))
    assert days == [date(2024, 1, 30)]


def test_start_after_end_raises():
    with pytest.raises(ValueError):
        days_between(date(2024, 2, 2), date(2024, 1, 30))
    with pytest.raises(ValueError):
        business_days(date(2024, 2, 2), date(2024, 1, 30))


